	GpioLed2.GPIO_PinConfig.GPIO_PinPuPdCtlr  = GPIO_NO_PUPD;

	GPIO_Init(&GpioLed2);
	GpioLed2.pGPIOx = GPIOA;
	GpioLed2.GPIO_PinConfig.GPIO_PinNum       = GPIO_PIN7;
	GpioLed2.GPIO_PinConfig.GPIO_PinMode      = GPIO_MODE_OUT;
	GpioLed2.GPIO_PinConfig.GPIO_PinSpeed     = GPIO_SPEED_FST;
	GpioLed2.GPIO_PinConfig.GPIO_PinOPType    = GPIO_OPT_PP;
