	USART2GPIO.GPIO_PinConfig.GPIO_PinPuPdCtlr  = GPIO_NO_PUPD;
	USART2GPIO.GPIO_PinConfig.GPIO_PinOPType    = GPIO_OPT_PP;
	USART2GPIO.GPIO_PinConfig.GPIO_PinSpeed     = GPIO_SPEED_FST;
	GPIO_Init(&USART2GPIO);

	USART2GPIO.GPIO_PinConfig.GPIO_PinNum       = GPIO_PIN3;
	GPIO_Init(&USART2GPIO);

	USART2Handler.pUSARTx = USART2;
	USART2Handler.USART_PinConfig.USARTx_Mode 		= USART_MODE_TXRX;
	USART2Handler.USART_PinConfig.USARTx_BaudRate 	= USART_STD_BAUD_115200;
