	GPIO_Init(&CSGPIO); //CS

	SPI22GPIO.pGPIOx = GPIOB;
	SPI22GPIO.GPIO_PinConfig.GPIO_PinPuPdCtlr  	= GPIO_NO_PUPD;
	SPI22GPIO.GPIO_PinConfig.GPIO_PinOPType    	= GPIO_OPT_PP;
