uint8_t hex2ascii(uint8_t nibble){
	if(nibble < 10){
		return nibble + '0';
	}
	else{
		return (nibble-10) + 'A';
	}
}

void PrintHex(USART_Handle_t *pUSARTx, uint8_t value){

	uint8_t hex[3];

	hex[0] = hex2ascii((value >> 4) & 0x0F);
	hex[1] = hex2ascii(value & 0x0F);
	hex[2] = ' ';

	USART_SendData(&USART2Handler, hex, 3);
}

