void TIM1_BRK_TIM9_IRQHandler(void){
	if(TIM9->SR & TIM_FLAG_UIF){
		cnt++;
		if(debounce_active){
			debounce_cnt--;
			if(debounce_cnt <= 0){
				debounce_ready = SET;
				debounce_active = 0;
			}
		}
		TIM9->SR &= ~TIM_FLAG_UIF;
	}
}

void USART2_IRQHandler(){
	if(USART2->SR & USART_FLAG_RXNE){
		if(ringBuffer_push(&rb, USART2->DR) == rb_full){
			usart2_error_flag = 1;
		}
	}
}

void EXTI15_10_IRQHandler(){

	if(EXTI->PR & (1 << 13)){
		EXTI->IMR &= ~(1U << 13);
		debounce_cnt = 2;
		debounce_active = SET;
		GPIO_IRQHandling(13);
	}
}
